{"command": "python3 -c "
from PIL import Image, ImageDraw, ImageOps, ImageFilter
im=Image.open('pantomograph.jpg').convert('L')
def g(name,x0,y0,x1,y1,s=3):
    c=im.crop((x0,y0,x1,y1)); c=ImageOps.autocontrast(c,cutoff=0.5).convert('RGB')
    c=c.resize((int((x1-x0)*s),int((y1-y0)*s)))
    d=ImageDraw.Draw(c)
    for x in range((x0//25+1)*25,x1,25):
        d.line([((x-x0)*s,0),((x-x0)*s,(y1-y0)*s)],fill=(255,0,0) if x%100==0 else (0,90,255) if x%50==0 else (0,50,90))
        if x%50==0: d.text(((x-x0)*s+2,2),str(x),fill=(255,255,0))
    for y in range((y0//25+1)*25,y1,25):
        d.line([(0,(y-y0)*s),((x1-x0)*s,(y-y0)*s)],fill=(255,0,0) if y%100==0 else (0,90,255) if y%50==0 else (0,50,90))
        if y%50==0: d.text((2,(y-y0)*s+2),str(y),fill=(255,255,0))
    c.save('/tmp/'+name+'.png')
g('z1',1150,580,1480,830)
g('z2',1560,580,1880,830)
"", "description": "Zoom lower canine/premolar regions"}

